import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Load GLB mesh (synchronous cache)
  const meshGroup = ctx.glbLoader.get(config.assets.meshUrl);
  const meshClone = meshGroup.clone(true);

  // Apply scene placement
  meshClone.position.set(
    config.scenePlacement.position.x,
    config.scenePlacement.position.y,
    config.scenePlacement.position.z
  );
  meshClone.rotation.set(
    config.scenePlacement.rotation.x,
    config.scenePlacement.rotation.y,
    config.scenePlacement.rotation.z
  );
  meshClone.scale.set(
    config.scenePlacement.scale.x,
    config.scenePlacement.scale.y,
    config.scenePlacement.scale.z
  );

  // Root object
  const root = new THREE.Group();
  root.add(meshClone);
  root.userData.handlers = {};

  // Hover timeline (rise-in preset, subtle 0.15 units)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(meshClone.position, {
    y: meshClone.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
    overwrite: 'auto'
  });

  root.userData.handlers.hover = {
    enter: () => hoverTimeline.play(),
    leave: () => hoverTimeline.reverse()
  };

  // Click handler – emit hub-collection.select
  root.userData.handlers.click = () => {
    if (ctx.events && ctx.events.emit) {
      ctx.events.emit('hub-collection.select', { source: config.id });
    } else {
      console.warn('No emit function available');
    }
  };

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach(prim => {
      const applyPrim = ctx.primitives[prim.name];
      if (applyPrim) {
        applyPrim(root, prim.params);
      } else {
        console.warn(`Primitive "${prim.name}" not found in ctx.primitives`);
      }
    });
  }

  // Cleanup
  root.userData.cleanup = () => {
    hoverTimeline.kill();
    // Dispose cloned mesh resources (geometries, materials)
    meshClone.traverse(child => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return root;
}
